// @ts-nocheck
import { render } from '@solidjs/web';
import { For, Loading } from 'solid-js';

import useRedux from './useRedux';
import reduxStore from './store';
import actions from './actions';

const App = () => {
  const [store, { addTodo, toggleTodo }] = useRedux(reduxStore, actions);
  let input;
  return (
    <>
      <div>
        <input ref={input} />
        <button
          onClick={(e) => {
            if (!input.value.trim()) return;
            addTodo(input.value);
            input.value = '';
          }}
        >
          Add Todo
        </button>
      </div>
      <Loading fallback={<p>Loading todos...</p>}>
        <For each={store.todos}>
          {(todo) => {
            console.log('Create todo');
            return (
              <div>
                <input
                  type="checkbox"
                  checked={todo.completed}
                  onChange={() => toggleTodo(todo.id)}
                />
                <span
                  style={{
                    'text-decoration': todo.completed ? 'line-through' : 'none',
                  }}
                >
                  {todo.text}
                </span>
              </div>
            );
          }}
        </For>
      </Loading>
    </>
  );
};

render(App, document.getElementById('app'));

import { createStore, from } from 'solid-js';

export default function useRedux(store, actions) {
  const [state] = createStore(() => store.getState(), { todos: [] });
  const mapped = {};
  for (const key in actions)
    mapped[key] = (...args) => store.dispatch(actions[key](...args));
  return [state, mapped];
}

let nextTodoId = 0;
export default {
  addTodo: (text) => ({ type: 'ADD_TODO', id: ++nextTodoId, text }),
  toggleTodo: (id) => ({ type: 'TOGGLE_TODO', id }),
};

// @ts-nocheck
function createStore(reducer) {
  let state = reducer(undefined, { type: 'INIT' });
  const listeners = new Set();
  return {
    getState: () => state,
    dispatch(action) {
      state = reducer(state, action);
      listeners.forEach((listener) => listener());
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

// todos reducer
const todos = (state = { todos: [] }, action) => {
  switch (action.type) {
    case 'ADD_TODO':
      return {
        todos: [
          ...state.todos,
          {
            id: action.id,
            text: action.text,
            completed: false,
          },
        ],
      };
    case 'TOGGLE_TODO':
      return {
        todos: state.todos.map((todo) =>
          todo.id === action.id
            ? { ...todo, completed: !todo.completed }
            : todo,
        ),
      };
    default:
      return state;
  }
};

export default createStore(todos);

